// orders · кейсы ord-02, ord-08, ord-09, ord-10, ord-11, ord-12, ord-13 (.qa/tests/orders/) — מחזור חיי הזמנה
// beforeAll: buyer сам создаёт 2 заказа «QA-AUTO-orders-e2e-…» (A — для правки/утверждения/משלוח/תשלום, B — для отклонения).
// Реальные заказы не трогаются. afterAll: всё, что осталось «ממתינה לאישור», отклоняется с причиной «QA-AUTO cleanup».
// Корзина buyer общая на сервере → не запускать параллельно с client-ordering/cart-checkout.spec.ts.
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const ITEM = { id: '340b7b2b-e022-4f3b-a6f0-f9a3dc8ecfe8', name: 'מצית קליפט' }; // ₪5.00 у клиента test
const orders: { A?: string; B?: string } = {};

async function emptyCart(page: Page) {
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible();
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  // ждём загрузки корзины (staging бывает медленным): либо есть позиции, либо «העגלה ריקה»
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  while (await remove.count()) {
    await remove.first().click();
    await page.waitForTimeout(500);
  }
  await expect(page.getByText('העגלה ריקה')).toBeVisible();
}

async function buyerPlaceOrder(browser: Browser, qty: number, note: string): Promise<string> {
  const ctx = await browser.newContext({ storageState: auth('buyer') });
  const page = await ctx.newPage();
  await emptyCart(page);
  await page.goto(`/shop/p/${ITEM.id}`);
  await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
  await page.goto('/shop/cart');
  for (let i = 1; i < qty; i++) await page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` }).click();
  await expect(page.getByText('סה״כ משוער').locator('..')).toContainText(`₪${(qty * 5).toFixed(2)}`);
  await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
  await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
  await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
  await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
  const no = (await page.getByText(/^הזמנה\s*#\d+/).first().innerText()).match(/#(\d+)/)![1];
  await ctx.close();
  return no;
}

async function openOrder(page: Page, no: string) {
  await page.goto('/orders');
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  const orderRow = page.getByRole('button', { name: new RegExp(`^#${no} `) });
  await expect(orderRow).toBeVisible({ timeout: 20_000 });
  await orderRow.click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
}

async function reject(page: Page, no: string, reason = 'QA-AUTO cleanup') {
  await page.getByRole('button', { name: 'דחייה' }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: `דחיית הזמנה #${no}` })).toBeVisible();
  await expect(dlg.getByRole('button', { name: 'דחה הזמנה' })).toBeDisabled();
  await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill(reason);
  await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
}

const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');

test.describe('orders — מחזור חיי הזמנה (QA-AUTO)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    const stamp = Date.now();
    orders.A = await buyerPlaceOrder(browser, 2, `QA-AUTO-orders-e2e-A-${stamp}`);
    orders.B = await buyerPlaceOrder(browser, 1, `QA-AUTO-orders-e2e-B-${stamp}`);
  });

  test.afterAll(async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: auth('admin') });
    const page = await ctx.newPage();
    for (const no of [orders.A, orders.B]) {
      if (!no) continue;
      await openOrder(page, no);
      if (await page.getByRole('button', { name: 'דחייה' }).count()) {
        await reject(page, no);
        await expect(header(page)).toContainText('נדחתה');
      }
    }
    await ctx.close();
  });

  test('הזמנה חדשה מופיעה ראשונה ברשימה; פרטים: פריטים, מחיר פר-לקוח, הערת לקוח, משלוח חסום עד אישור #6a38cf5f #6a38cf5c @desktop', async ({ page }) => {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    const row = page.getByRole('button', { name: new RegExp(`^#${orders.A} `) });
    await expect(row).toBeVisible({ timeout: 20_000 });
    await expect(row).toHaveAccessibleName(/test .*₪10\.00 לא שולם ממתינה לאישור/);
    await row.click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orders.A}` })).toBeVisible();
    await expect(header(page)).toContainText('ממתינה לאישור');
    await expect(page.getByRole('heading', { name: 'פריטי ההזמנה' })).toBeVisible();
    await expect(page.getByText(ITEM.name, { exact: true })).toBeVisible();
    await expect(page.getByText('סה"כ לתשלום').locator('..')).toContainText('₪10.00');
    await expect(page.getByRole('heading', { name: 'הערת לקוח' })).toBeVisible();
    await expect(page.getByText(/^QA-AUTO-orders-e2e-A-/)).toBeVisible();
    await expect(page.getByText('איש קשר')).toBeVisible();
    // TC-050: по умолчанию «לא שולם»; TC-049/#6a71f0ec: משלוח нельзя двигать до утверждения
    await expect(page.getByText('נותר לתשלום').locator('..')).toContainText('₪10.00');
    await expect(page.getByRole('button', { name: 'סמן כמוכנה למשלוח' })).toBeDisabled();
    await expect(page.getByText('יש לאשר את ההזמנה לפני עדכון סטטוס המשלוח.')).toBeVisible();
  });

  test('הזמנה ללא מוצרים — «שמור שינויים» מושבת, לא ניתן לשמור/לאשר #6a72faf3 #6a38cf5b @desktop', async ({ page }) => {
    await openOrder(page, orders.A!);
    await page.getByRole('button', { name: 'עריכה' }).click();
    await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${orders.A}` })).toBeVisible();
    await page.getByRole('button', { name: `הסרת ${ITEM.name}` }).click();
    await expect(page.getByText('ההזמנה ריקה — הוסף לפחות פריט אחד כדי לשמור.')).toBeVisible();
    await expect(page.getByText('סה"כ לתשלום').locator('..')).toContainText('₪0.00');
    await expect(page.getByRole('button', { name: 'שמור שינויים' })).toBeDisabled();
    await page.getByRole('button', { name: 'ביטול' }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orders.A}` })).toBeVisible();
    await expect(page.getByText('סה"כ לתשלום').locator('..')).toContainText('₪10.00');
  });

  test('עריכה לפני אישור: כמות מעדכנת סכום, הסרה והוספה מהחיפוש, תיעוד מי ערך ומתי #6a38cf5b @desktop', async ({ page }) => {
    await openOrder(page, orders.A!);
    await page.getByRole('button', { name: 'עריכה' }).click();
    await expect(page.getByText('עריכת פריטים וכמויות לפני אישור סופי')).toBeVisible();
    const total = page.getByText('סה"כ לתשלום').locator('..');
    await page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` }).click();
    await expect(total).toContainText('₪15.00');

    await page.getByRole('button', { name: `הסרת ${ITEM.name}` }).click();
    await expect(total).toContainText('₪0.00');
    const search = page.getByRole('combobox', { name: 'חיפוש מוצר להוספה להזמנה' });
    await search.fill('קליפט');
    await expect(page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' }).getByRole('option', { name: /מצית קליפט/ })).toBeVisible();
    await search.press('Enter');
    await expect(total).toContainText('₪5.00');
    await expect(page.getByRole('button', { name: `הפחתת יחידה — ${ITEM.name}` })).toBeDisabled();
    await page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` }).click();
    await page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` }).click();
    await expect(total).toContainText('₪15.00');
    await page.getByRole('button', { name: 'שמור שינויים' }).click();

    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orders.A}` })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('סה"כ לתשלום').locator('..')).toContainText('₪15.00');
    await expect(page.getByRole('heading', { name: 'תיעוד עריכה' })).toBeVisible();
    await expect(page.getByText(/^ההזמנה נערכה בידי test admin בתאריך \d{2}\.\d{2}\.\d{4}/)).toBeVisible();
  });

  test('סטטוס תשלום: ולידציה (חורג/שלילי/0), שולם חלקית עם יתרה #6a38cf5c @desktop', async ({ page }) => {
    await openOrder(page, orders.A!);
    const box = page.getByRole('heading', { name: 'סטטוס תשלום' }).locator('../..');
    await expect(box).toContainText('לא שולם');
    await expect(box).toContainText('₪0.00 מתוך ₪15.00');
    await box.getByRole('button', { name: 'עדכון' }).click();
    await box.getByRole('combobox', { name: 'סטטוס תשלום' }).selectOption({ label: 'שולם חלקית' });
    const amount = box.getByRole('textbox', { name: 'סכום שהתקבל כעת' });
    const save = box.getByRole('button', { name: 'שמירה' });
    await expect(box.getByText('סכום שהתקבל כעת (עד ₪15.00 שנותרו)')).toBeVisible();
    await amount.fill('20');
    await expect(box.getByText('הסכום גבוה מהיתרה שנותרה — ₪15.00')).toBeVisible();
    await expect(save).toBeDisabled();
    for (const v of ['-5', '0']) {
      await amount.fill(v);
      await expect(box.getByText('יש להזין את הסכום שהתקבל')).toBeVisible();
      await expect(save).toBeDisabled();
    }
    await amount.fill('5');
    await expect(save).toBeEnabled();
    await save.click();
    await expect(box).toContainText('שולם חלקית');
    await expect(box).toContainText('₪5.00 מתוך ₪15.00');
    await expect(page.getByText('נותר לתשלום').locator('..')).toContainText('₪10.00');
    await expect(header(page)).toContainText('שולם חלקית');
  });

  test('אישור הזמנה עם הערה פנימית → «אושרה»; אחרי אישור אין עריכה ודחייה #6a38cf5b @desktop', async ({ page }) => {
    await openOrder(page, orders.A!);
    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: `אישור הזמנה #${orders.A}` })).toBeVisible();
    await dlg.getByRole('textbox', { name: 'הערה (לא חובה)' }).fill('QA-AUTO approve (orders e2e)');
    await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 20_000 });
    await expect(page.getByRole('button', { name: 'אישור הזמנה' })).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'דחייה' })).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'עריכה' })).toHaveCount(0);
    // возможная гонка в продукте: order_notes не перезапрашивается после approve_order — записано как находка.
    // Блок «הערות פנימיות» иногда не появляется без перезагрузки → перезагружаем перед проверкой заметки.
    await page.reload();
    await expect(page.getByRole('heading', { name: 'הערות פנימיות' })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('QA-AUTO approve (orders e2e)')).toBeVisible({ timeout: 20_000 });
  });

  test('משלוח: «מוכן למשלוח» נשמר אחרי רענון → «בדרך ללקוח» → «סופק» עם תאריך, בלי דילוג #6a71f0ec #6a38cf5c @desktop', async ({ page }) => {
    await openOrder(page, orders.A!);
    const ship = page.getByRole('heading', { name: 'משלוח' }).locator('../..');
    await expect(ship.getByRole('button', { name: 'סמן כסופקה' })).toHaveCount(0);
    await ship.getByRole('button', { name: 'סמן כמוכנה למשלוח' }).click();
    await expect(header(page)).toContainText('מוכנה למשלוח');
    await page.reload();
    await expect(header(page)).toContainText('מוכנה למשלוח', { timeout: 20_000 });
    await expect(page.getByText('ההזמנה ארוזה וממתינה ליציאת הנהג')).toBeVisible();
    await expect(page.getByRole('button', { name: 'סמן כסופקה' })).toHaveCount(0);

    await page.getByRole('button', { name: 'סמן כיצאה למשלוח' }).click();
    await expect(header(page)).toContainText('בדרך ללקוח');
    await page.getByRole('button', { name: 'סמן כסופקה' }).click();
    await expect(header(page)).toContainText('סופקה');
    await expect(page.getByText('ההזמנה סופקה ללקוח')).toBeVisible();
    await expect(page.getByText('סופקה בתאריך').locator('..')).toContainText(/\d{2}\.\d{2}\.\d{4}, \d{2}:\d{2}/);
  });

  test('דחיית הזמנה: סיבה חובה, סטטוס «נדחתה», הסיבה מוצגת #6a38cf5b @desktop', async ({ page }) => {
    await openOrder(page, orders.B!);
    await reject(page, orders.B!, 'QA-AUTO cleanup');
    await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
    await expect(page.getByRole('heading', { name: 'סיבת הדחייה' })).toBeVisible();
    await expect(page.getByText('QA-AUTO cleanup', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'אישור הזמנה' })).toHaveCount(0);
  });
});
